B.U3=new A.K("Jet Printer Excel & Scan Verification","\u0686\u0627\u067e \u0627\u0632 \u0627\u06a9\u0633\u0644 \u0628\u0627 \u0686\u0627\u067e\u06af\u0631 \u0635\u0646\u0639\u062a\u06cc \u0648 \u062a\u0623\u06cc\u06cc\u062f \u0628\u0627 \u0627\u0633\u06a9\u0646\u0631")
B.Ry=new A.K("Flutter desktop app \u2014 reads Excel files, sends print commands to industrial Jet Printers, and verifies output with a barcode scanner.","\u0627\u067e \u062f\u0633\u06a9\u062a\u0627\u067e Flutter \u2014 \u0641\u0627\u06cc\u0644 \u0627\u06a9\u0633\u0644 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0646\u062f\u060c \u0628\u0647 \u0686\u0627\u067e\u06af\u0631 \u0635\u0646\u0639\u062a\u06cc \u062f\u0633\u062a\u0648\u0631 \u0686\u0627\u067e \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u062e\u0631\u0648\u062c\u06cc \u0631\u0627 \u0628\u0627 \u0627\u0633\u06a9\u0646\u0631 \u0628\u0627\u0631\u06a9\u062f \u062a\u0623\u06cc\u06cc\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.")
B.pX=new A.K("Industrial Desktop App","\u0627\u067e \u062f\u0633\u06a9\u062a\u0627\u067e \u0635\u0646\u0639\u062a\u06cc")
